-- Publish corrected authored copy with existing verified prices and dates. No provider calls.
-- Read this UTF-8 file explicitly as UTF-8; do not use legacy Windows ANSI decoding.
BEGIN;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
DO $copy$
DECLARE payload jsonb; cards jsonb:='[]'; c jsonb; fresh jsonb; f jsonb; old_fact jsonb;
 facts jsonb; templates jsonb:=$templates$[{"key":"D001","description":"You need work, and money is tight. Look through the job postings and decide where to apply.","title":"Looking for work","facts":[{"role":"general","text":"Finding work can take time while everyday expenses continue.","template":"Finding work can take time while everyday expenses continue. In {period}, {pct}% of Sandy Springs civilian labor-force participants were unemployed.","semantic_key":"acs:B23025:unemployment","copy_kind":"context","source_url":"https://api.census.gov/data/2024/acs/acs5/groups.html","evidence":"**Player-facing general fact template:** “Finding work can take time while everyday expenses continue. In {period}, {pct}% of Sandy Springs civilian labor-force participants were unemployed.”\n\n**General fact semantic key:** `acs:B23025:unemployment`\n\nSource/update: S05 / A02; [S26 table catalogue](https://api.census.gov/data/2024/acs/acs5/groups.html), table B23025. Unemployed / civilian labor force; exclude armed forces. Resolve exact estimate/MOE cells and Sandy Springs place geography against the selected annual five-year release; reject missing/suppressed values and zero denominators. Observation retrieval remains pending. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Building skills can be one part of preparing for the search for work. In 2025, CAC reported 610 total students in Adult Education programs.","template":"Building skills can be one part of preparing for the search for work. In 2025, CAC reported 610 total students in Adult Education programs.","semantic_key":"7cb64039-5726-43da-8f15-fbf8b63e8f83","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Building skills can be one part of preparing for the search for work. In 2025, CAC reported 610 total students in Adult Education programs.”\n\nSource: S18/S19; fact ID `7cb64039-5726-43da-8f15-fbf8b63e8f83`; service `adult_education`; key `total_students_in_adult_education_programs`; reporting year 2025; exact stored value `610` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The choice explicitly includes adult English/computer preparation before selecting a job. Conditional free CAC preparation; USD 0.00, no cash credit. Course totals do not determine skills, eligibility or wages.\n\n"}]},{"key":"D002","description":"Your interview is today. What will you wear?","title":"An interview today","facts":[{"role":"general","text":"An interview can bring hope and another expense when you need something to wear.","template":"An interview can bring hope and another expense when you need something to wear. In the past year, the average price of apparel {change} by {pct}%.","semantic_key":"cpi:SAA","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “An interview can bring hope and another expense when you need something to wear. In the past year, the average price of apparel {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SAA`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SAA. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Clothing can be an important part of looking professional. In 2025, clients used $206,768.67 in credits at CAC Canopy Thrift to receive essential clothing.","template":"Clothing can be an important part of looking professional. In 2025, clients used $206,768.67 in credits at CAC Canopy Thrift to receive essential clothing.","semantic_key":"859b8cec-1e1c-4887-9f55-fd55f1bb349c","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Clothing can be an important part of looking professional. In 2025, clients used $206,768.67 in credits at CAC Canopy Thrift to receive essential clothing.”\n\nSource: S18/S19; fact ID `859b8cec-1e1c-4887-9f55-fd55f1bb349c`; service `canopy_thrift`; key `dollar_amount_of_client_credits_used_at_cac_canopy_thrift`; reporting year 2025; exact stored value `206768.67` Dollars. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. Professional-clothing costs connect directly to the client-credit program. Existing conditional clothing pathway; annual credit does not set its amount.\n\n"}]},{"key":"D003","description":"The interview did not lead to a job. You still need work. Where will you apply next?","title":"Back to the job search","facts":[{"role":"general","text":"After an unsuccessful interview, the search continues.","template":"After an unsuccessful interview, the search continues. In {period}, {pct}% of Sandy Springs residents age 16 and older were not in the labor force.","semantic_key":"acs:B23025:not_in_labor_force","copy_kind":"context","source_url":"https://api.census.gov/data/2024/acs/acs5/groups/B23025.json","evidence":"**Player-facing general fact template:** “After an unsuccessful interview, the search continues. In {period}, {pct}% of Sandy Springs residents age 16 and older were not in the labor force.”\n\n**General fact semantic key:** `acs:B23025:not_in_labor_force`\n\nSource/update: https://api.census.gov/data/2024/acs/acs5/groups/B23025.json. Annual ACS five-year not-in-labor-force estimate, B23025_007E / B23025_001E, Georgia place 68516. Refreshed monthly when a new annual release becomes available. Approved revision from facts fixes.docx, November 15, 2026.\n"},{"role":"cac","text":"Career support connects with the effort of finding your next opportunity. In 2025, the Empowerment Center's Career Services helped 229 people.","template":"Career support connects with the effort of finding your next opportunity. In 2025, the Empowerment Center's Career Services helped 229 people.","semantic_key":"db12c137-fad7-4277-b4ca-6a203b344e38","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Career support connects with the effort of finding your next opportunity. In 2025, the Empowerment Center's Career Services helped 229 people.”\n\nSource: S18/S19; fact ID `db12c137-fad7-4277-b4ca-6a203b344e38`; service `career_services`; key `people_helped_by_career_services`; reporting year 2025; exact stored value `229` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. Reapplying after an unsuccessful interview is directly relevant to career support. Context only; retain no CAC choice and no automatic job placement.\n\n"}]},{"key":"D004","description":"You have another interview today. What will you wear?","title":"Another interview","facts":[{"role":"general","text":"Another interview can mean more time spent traveling and preparing, while keeping other needs in view.","template":"Another interview can mean more time spent traveling and preparing, while keeping other needs in view. In {period}, {pct}% of Sandy Springs workers who traveled to work had a commute of at least 60 minutes.","semantic_key":"acs:B08303:long_commute","copy_kind":"context","source_url":"https://api.census.gov/data/2024/acs/acs5/groups.html","evidence":"**Player-facing general fact template:** “Another interview can mean more time spent traveling and preparing, while keeping other needs in view. In {period}, {pct}% of Sandy Springs workers who traveled to work had a commute of at least 60 minutes.”\n\n**General fact semantic key:** `acs:B08303:long_commute`\n\nSource/update: S05 / A02; [S26 table catalogue](https://api.census.gov/data/2024/acs/acs5/groups.html), table B08303. Sum nonoverlapping 60+ minute brackets / workers with a reported journey to work; exclude home workers. Resolve exact estimate/MOE cells and Sandy Springs place geography against the selected annual five-year release; reject missing/suppressed values and zero denominators. Observation retrieval remains pending. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"In 2025, the CAC reported 80 job placements, helping people support themselves financially.","template":"In 2025, the CAC reported 80 job placements, helping people support themselves financially.","semantic_key":"2675ebbd-e014-4506-a0fd-1130a9ffe692","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “In 2025, the CAC reported 80 job placements, helping people support themselves financially.”\n\nSource: S18/S19; fact ID `2675ebbd-e014-4506-a0fd-1130a9ffe692`; service `career_services`; key `job_placements`; reporting year 2025; exact stored value `80` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. A follow-up interview is relevant to the reported job-placement outcome. Existing conditional clothing pathway is unchanged; placements do not determine scripted hiring.\n\n"}]},{"key":"D005","description":"It is time to file your taxes. Will you handle the return yourself or get help preparing it?","title":"Time to file taxes","facts":[{"role":"general","text":"The Earned Income Tax Credit can help working households keep more of their income. In tax year 2024, recipients nationwide received an average EITC of $2,894.","template":"The Earned Income Tax Credit can help working households keep more of their income. In tax year 2024, recipients nationwide received an average EITC of $2,894.","semantic_key":"irs:average_eitc","copy_kind":"fact","source_url":"https://www.irs.gov/tax-professionals/eitc-central/statistics-for-tax-returns-with-the-earned-income-tax-credit-eitc","evidence":"**Player-facing general fact:** “The Earned Income Tax Credit can help working households keep more of their income. In tax year 2024, recipients nationwide received an average EITC of $2,894.”\n\n**General fact semantic key:** `irs:average_eitc`\n\nSource/update: https://www.irs.gov/tax-professionals/eitc-central/statistics-for-tax-returns-with-the-earned-income-tax-credit-eitc. IRS recipient average, tax year 2024 processed in 2025. Retain this dated IRS observation without automatic website requests. The simulation uses authored credit amounts, independently of this observed national average. Approved revision from facts fixes.docx, November 15, 2026.\n"},{"role":"cac","text":"Tax preparation can connect households with money back at filing time. In 2025, CAC reported 503 tax returns through VITA and $672,056 in combined federal and state refunds.","template":"Tax preparation can connect households with money back at filing time. In 2025, CAC reported 503 tax returns through VITA and $672,056 in combined federal and state refunds.","semantic_key":"cac:vita:2025:returns_and_refunds","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Tax preparation can connect households with money back at filing time. In 2025, CAC reported 503 tax returns through VITA and $672,056 in combined federal and state refunds.”\n\n**CAC fact semantic key:** `cac:vita:2025:returns_and_refunds`\n\n**Composite CAC fact sources:** S18/S19; service `vita`; 2025 return-count record `5b9132c2-90d6-4dea-9dc0-f2de13a89e2f` = 503 Number; federal-refund record `7f25dabd-f5a5-4a54-9201-fd5f3ccd173d` = USD 582083; state-refund record `d4d72fe4-20b1-4a1b-97a4-dea745b7e4f7` = USD 89973. Derived total: 582083 + 89973 = USD 672056. This is one player-facing CAC passage backed by three observations, not three fact slots. Require matching reporting years, compatible scopes and complete inputs before automatically updating the passage; never add tax-credit totals to refunds, divide this total by 503, or infer 503 unique recipients. Count and refund observations are reported program measures, not a verified matched cohort. Exact original source verification remains pending; the snapshot verifies the stored figures. The passage does not set the simulated household refund. Historical pairing files remain the earlier single-record proposal; this composite supersedes it for D005 final binding.\n\n**Required occurrence - user decision, November 7, 2026:** D005 is mandatory once in every playthrough, in both support modes and for every persona. Reserve a scheduled ordinary-day slot; it must not be omitted by random selection, selected again, or collide with employment events. This supersedes earlier non-scheduled/optional sampling instructions for D005. The exact due day remains to be configured; the earlier Day 18 is a proposal, not a newly approved day. Early-ended runs cannot show later days: they may end before reaching the reserved tax event, but every complete route must include it. Existing early-ending rules are unchanged. If literal display before every possible early ending is required, its placement needs a separate explicit change; no new pre-game event is inferred. Verify exactly-once inclusion, all personas/modes, routing and refresh restoration. This is a documentation requirement; scheduling is not implemented here.\n\n"}]},{"key":"D006","description":"Rent is due. Paying it will leave less money for groceries, transportation, and everything else.","title":"Rent is due","facts":[{"role":"general","text":"When rent comes due, keeping a roof over your head can leave less for everything else.","template":"When rent comes due, keeping a roof over your head can leave less for everything else. In {period}, {pct}% of Sandy Springs renter households with a reported rent-to-income ratio spent at least 30% of their income on gross rent.","semantic_key":"acs:B25070:rent_burden","copy_kind":"context","source_url":"https://api.census.gov/data/2024/acs/acs5/groups.html","evidence":"**Player-facing general fact template:** “When rent comes due, keeping a roof over your head can leave less for everything else. In {period}, {pct}% of Sandy Springs renter households with a reported rent-to-income ratio spent at least 30% of their income on gross rent.”\n\n**General fact semantic key:** `acs:B25070:rent_burden`\n\nSource/update: S05 / A02; [S26 table catalogue](https://api.census.gov/data/2024/acs/acs5/groups.html), table B25070. Sum 30%+ brackets / computed-ratio households; retain MOEs. Resolve exact estimate/MOE cells and Sandy Springs place geography against the selected annual five-year release; reject missing/suppressed values and zero denominators. Observation retrieval remains pending. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Keeping housing stable is at the heart of CAC eviction prevention. In 2025, CAC reported preventing evictions for 1,108 households.","template":"Keeping housing stable is at the heart of CAC eviction prevention. In 2025, CAC reported preventing evictions for 1,108 households.","semantic_key":"5fa2bac7-6016-4db8-b705-fc593f6b75ec","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Keeping housing stable is at the heart of CAC eviction prevention. In 2025, CAC reported preventing evictions for 1,108 households.”\n\nSource: S18/S19; fact ID `5fa2bac7-6016-4db8-b705-fc593f6b75ec`; service `eviction_prevention`; key `evictions_prevented`; reporting year 2025; exact stored value `1108` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The obligation is rent and the fact is specifically about eviction prevention. Existing conditional rent pathway; no eligibility or coverage amount inferred.\n\n"}]},{"key":"D007","description":"The electricity bill is due. Your household still needs groceries and transportation this month. Which obligation will you carry?","title":"Keeping the lights on","facts":[{"role":"general","text":"Electricity keeps a household running.","template":"Electricity keeps a household running. In {period}, Georgia residential electricity customers paid an average monthly bill of ${monthly_bill}, calculated from EIA residential revenue and customer counts.","semantic_key":"eia:GA:residential_monthly_bill","copy_kind":"context","source_url":"https://api.eia.gov/v2/electricity/retail-sales/","evidence":"**Player-facing general fact template:** “Electricity keeps a household running. In {period}, Georgia residential electricity customers paid an average monthly bill of ${monthly_bill}, calculated from EIA residential revenue and customer counts.”\n\n**General fact semantic key:** `eia:GA:residential_monthly_bill`\n\nSource/update: https://api.eia.gov/v2/electricity/retail-sales/. Use monthly residential Georgia revenue in million dollars divided by residential customer count, multiplied by 1,000,000. This is a Georgia customer average, not a Sandy Springs tariff. Bill amount and fact use the same observation. Approved revision from facts fixes.docx, November 15, 2026.\n"},{"role":"cac","text":"Utilities and rent draw on the money needed to keep a home. In 2025, CAC reported preventing evictions for 1,108 households.","template":"Utilities and rent draw on the money needed to keep a home. In 2025, CAC reported preventing evictions for 1,108 households.","semantic_key":"5fa2bac7-6016-4db8-b705-fc593f6b75ec","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Utilities and rent draw on the money needed to keep a home. In 2025, CAC reported preventing evictions for 1,108 households.”\n\nSource: S18/S19; fact ID `5fa2bac7-6016-4db8-b705-fc593f6b75ec`; service `eviction_prevention`; key `evictions_prevented`; reporting year 2025; exact stored value `1108` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. Electricity costs compete with rent and other essentials, connecting this decision to housing stability and eviction prevention. The user confirmed rent and utility bill support through CAC eviction prevention. Offer conditional CAC bill support in CAC mode; validate household eligibility and availability, cap assistance at the eligible bill balance, and bind the approved coverage amount separately from annual facts.\n\n"}]},{"key":"D008","description":"A water and sewer bill arrives. It is smaller than rent, but paying every small bill still adds up.","title":"The water bill","facts":[{"role":"general","text":"A water bill is another essential expense competing for the money you have.","template":"A water bill is another essential expense competing for the money you have. In the past year, the average price of water and sewerage maintenance {change} by {pct}%.","semantic_key":"cpi:SEHG01","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “A water bill is another essential expense competing for the money you have. In the past year, the average price of water and sewerage maintenance {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SEHG01`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SEHG01. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Water and sewer costs share the household budget with rent and other essentials. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.","template":"Water and sewer costs share the household budget with rent and other essentials. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.","semantic_key":"b697ae84-1fd2-4bae-83da-7a10c983ac24","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Water and sewer costs share the household budget with rent and other essentials. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.”\n\nSource: S18/S19; fact ID `b697ae84-1fd2-4bae-83da-7a10c983ac24`; service `financial_assistance`; key `amount_paid_through_financial_assistance`; reporting year 2025; exact stored value `796416.64` Dollars. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. Water and sewer costs are part of household housing pressure, providing context for financial assistance to prevent homelessness. The user confirmed rent and utility bill support through CAC eviction prevention. Offer conditional CAC bill support in CAC mode; validate household eligibility and availability, cap assistance at the eligible bill balance, and bind the approved coverage amount separately from annual facts.\n\n"}]},{"key":"D009","description":"Your phone plan renews today. Keeping it paid competes with the money you were trying to save for an emergency.","title":"Staying connected","facts":[{"role":"general","text":"A phone connection can be mandatory for keeping up with work, family and daily responsibilities.","template":"A phone connection can be mandatory for keeping up with work, family and daily responsibilities. It is the second most common household bill, surpassed only by electricity. In the past year, the average price of wireless telephone services {change} by {pct}%.","semantic_key":"cpi:SEED03","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “A phone connection can be mandatory for keeping up with work, family and daily responsibilities. It is the second most common household bill, surpassed only by electricity. In the past year, the average price of wireless telephone services {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SEED03`\n\nSource/update: https://www.bls.gov/cpi/additional-resources/index-publication-level.htm. User supplied Telecompetitor summary https://www.telecompetitor.com/u-s-households-pay-1200-per-year-for-mobile-phone-service-on-average/ reports a $100 monthly median. Retain 2026 for the ranking. CPI-U CUUR0000SEED03 supplies the rolling 12-month category price change. Approved revision from facts fixes.docx, November 15, 2026.\n"},{"role":"cac","text":"Bills can start to add up and cause stress for the money needed to keep a home. In 2025, CAC reported preventing evictions for 1,108 households.","template":"Bills can start to add up and cause stress for the money needed to keep a home. In 2025, CAC reported preventing evictions for 1,108 households.","semantic_key":"5fa2bac7-6016-4db8-b705-fc593f6b75ec","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “Bills can start to add up and cause stress for the money needed to keep a home. In 2025, CAC reported preventing evictions for 1,108 households.”\n\nSource fact ID `5fa2bac7-6016-4db8-b705-fc593f6b75ec`\n\nSource/update: https://ourcac.org/. CAC 2025 repository snapshot. evictions prevented: 1108 Number. Reporting year 2025. Annual refresh requires a CAC-provided report/export. User approved this pairing November 15, 2026. Approved revision from facts fixes.docx, November 15, 2026.\n\n"}]},{"key":"D010","description":"Your internet bill is due. You use the connection for applications and household tasks, but it does not replace the phone bill.","title":"The internet bill","facts":[{"role":"general","text":"Internet access is part of everyday life for most adults. In a 2025 U.S. survey, 90% of adults said they used the internet every day.","template":"Internet access is part of everyday life for most adults. In a 2025 U.S. survey, 90% of adults said they used the internet every day.","semantic_key":"digital:adult_daily_internet_use","copy_kind":"fact","source_url":"https://www.pewresearch.org/short-reads/2026/01/08/internet-use-smartphone-ownership-digital-divides-in-u-s/","evidence":"**Player-facing general fact:** “Internet access is part of everyday life for most adults. In a 2025 U.S. survey, 90% of adults said they used the internet every day.”\n\n**General fact semantic key:** `digital:adult_daily_internet_use`\n\nSource/update: S29, [Pew Research Center: Internet use and digital divides](https://www.pewresearch.org/short-reads/2026/01/08/internet-use-smartphone-ownership-digital-divides-in-u-s/), published January 8, 2026; survey February 5-June 18, 2025. Daily use includes almost constantly, several times daily and about once daily; denominator all U.S. adults, not only internet users. Exact observed value 90 percent. Source checked November 7, 2026. This demonstrates everyday use, not that every activity requires internet or a paid home broadband subscription. Proposed copy; initial binding verification pending. Retain the survey year and source observation; monitor later releases through a configured backend report import with schema/population checks and automatic validated edition publication. No free-form claim regeneration.\n"},{"role":"cac","text":"Home internet is another bill competing for the money needed to maintain a household. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.","template":"Home internet is another bill competing for the money needed to maintain a household. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.","semantic_key":"b697ae84-1fd2-4bae-83da-7a10c983ac24","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Home internet is another bill competing for the money needed to maintain a household. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.”\n\nSource: S18/S19; fact ID `b697ae84-1fd2-4bae-83da-7a10c983ac24`; service `financial_assistance`; key `amount_paid_through_financial_assistance`; reporting year 2025; exact stored value `796416.64` Dollars. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The home-internet bill competes with rent and other household obligations, providing broader housing-budget context for financial assistance to prevent homelessness. The user confirmed rent and utility bill support through CAC eviction prevention. Offer conditional CAC bill support in CAC mode; validate household eligibility and availability, cap assistance at the eligible bill balance, and bind the approved coverage amount separately from annual facts.\n\n"}]},{"key":"D011","description":"A car insurance installment is due. Ignoring it preserves cash today while leaving a larger amount unpaid.","title":"Car insurance is due","facts":[{"role":"general","text":"The price of car insurance isn’t the same for every person. Factors for higher costs can include being a home renter, having less education, being a blue-collar worker, or having a lower credit score, factors that disproportionately affect lower-income individuals.","template":"The price of car insurance isn’t the same for every person. Factors for higher costs can include being a home renter, having less education, being a blue-collar worker, or having a lower credit score, factors that disproportionately affect lower-income individuals.","semantic_key":"insurance:non_driving_rating_factors","copy_kind":"fact","source_url":"https://consumerfed.org/news/testimony-comments/auto-insurance-rating-factors-and-their-effect-on-different-demographics-of-consumers/","evidence":"**Player-facing general fact:** “The price of car insurance isn’t the same for every person. Factors for higher costs can include being a home renter, having less education, being a blue-collar worker, or having a lower credit score, factors that disproportionately affect lower-income individuals.”\n\n**General fact semantic key:** `insurance:non_driving_rating_factors`\n\nSource/update: https://consumerfed.org/news/testimony-comments/auto-insurance-rating-factors-and-their-effect-on-different-demographics-of-consumers/.  Approved revision from facts fixes.docx, November 15, 2026.\n"},{"role":"cac","text":"Deciding how to handle an insurance bill is part of managing financial demands. In 2025, 218 students enrolled in Financial Literacy Classes.","template":"Deciding how to handle an insurance bill is part of managing financial demands. In 2025, 218 students enrolled in Financial Literacy Classes.","semantic_key":"d32689c8-067a-4f59-aa48-2424384b7116","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Deciding how to handle an insurance bill is part of managing financial demands. In 2025, 218 students enrolled in Financial Literacy Classes.”\n\nSource: S18/S19; fact ID `d32689c8-067a-4f59-aa48-2424384b7116`; service `financial_literacy_classes`; key `students_enrolled_in_financial_literacy_classes`; reporting year 2025; exact stored value `218` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. Choosing how to handle an insurance installment is a financial-literacy/budget tradeoff. Context only; no CAC car-insurance payment or insurance service inferred.\n\n"}]},{"key":"D012","description":"A bill from an earlier clinic visit comes due.","title":"A clinic bill arrives","facts":[{"role":"general","text":"In the Federal Reserve's 2025 U.S. survey, adults with lower family incomes were more likely to have gone without medical care because they could not afford it.","template":"In the Federal Reserve's 2025 U.S. survey, adults with lower family incomes were more likely to have gone without medical care because they could not afford it.","semantic_key":"health:income_related_forgone_care","copy_kind":"fact","source_url":"https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-economic-hardships.htm","evidence":"**Player-facing general fact:** “In the Federal Reserve's 2025 U.S. survey, adults with lower family incomes were more likely to have gone without medical care because they could not afford it.”\n\n**General fact semantic key:** `health:income_related_forgone_care`\n\nSource/update: S30, [Federal Reserve: economic hardships](https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-economic-hardships.htm). Income-group comparison of forgone care; association, not proof of causation. Source checked November 7, 2026. Proposed qualitative display copy; initial content verification remains pending. Preserve the dated observation and semantic key on routine refresh; do not regenerate free-form claims automatically. No numerical binding is required for this passage.\n"}]},{"key":"D013","description":"Maya’s agreed childcare arrangement has an invoice due. Paying it uses money you had hoped to keep available for the rest of the month.","title":"The childcare bill","facts":[{"role":"general","text":"Childcare can be one of a family's largest expenses. In the Federal Reserve's 2025 U.S. survey, most families paying for both childcare and housing spent at least half as much on childcare as on rent or mortgage payments.","template":"Childcare can be one of a family's largest expenses. In the Federal Reserve's 2025 U.S. survey, most families paying for both childcare and housing spent at least half as much on childcare as on rent or mortgage payments.","semantic_key":"care:childcare_cost_relative_to_housing","copy_kind":"fact","source_url":"https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-living-arrangements-care-work.htm","evidence":"**Player-facing general fact:** “Childcare can be one of a family's largest expenses. In the Federal Reserve's 2025 U.S. survey, most families paying for both childcare and housing spent at least half as much on childcare as on rent or mortgage payments.”\n\n**General fact semantic key:** `care:childcare_cost_relative_to_housing`\n\nSource/update: S31, [Federal Reserve: Living Arrangements and Care Work](https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-living-arrangements-care-work.htm), childcare section and figure 13, published May 2026. Population: families paying for both childcare and housing; national 2025 survey, not a Sandy Springs estimate. Source explicitly reports the majority comparison; this is not a ratio of the two published medians. Monthly childcare costs use weekly payments multiplied by 52/12; housing is rent or mortgage payments. Source checked November 8, 2026. Initial binding verification pending. Check monthly for annual SHED releases; replace the dated comparison only when the same population and calculation are validated from a configured report/data import. Otherwise retain the 2025 statement and flag unavailable or changed source structure; do not automatically rewrite the claim. This fact does not set the scenario's bill amount.\n"},{"role":"cac","text":"Often, childcare costs do not end at the price for a care program. The CAC offers free coats for kids and school supply bags to help families when the costs start to add up. In 2025, Coats for Kids served 623 children.","template":"Often, childcare costs do not end at the price for a care program. The CAC offers free coats for kids and school supply bags to help families when the costs start to add up. In 2025, Coats for Kids served 623 children.","semantic_key":"e8473e58-6338-4855-93be-7608f27696ab","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “Often, childcare costs do not end at the price for a care program. The CAC offers free coats for kids and school supply bags to help families when the costs start to add up. In 2025, Coats for Kids served 623 children.”\n\nSource fact ID `e8473e58-6338-4855-93be-7608f27696ab`\n\nSource/update: https://ourcac.org/. CAC 2025 repository snapshot. children served by Coats for Kids: 623 Number. Reporting year 2025. Annual refresh requires a CAC-provided report/export. User approved this pairing November 15, 2026. Approved revision from facts fixes.docx, November 15, 2026.\n\n"}]},{"key":"D014","description":"Maya needs school lunches for the month. How will you handle the bill?","title":"Maya's school meal balance","facts":[{"role":"general","text":"Studies have demonstrated that school meal programs play an important role in overall student health and academic achievement by improving children’s diets and combatting hunger. The National School Lunch Program helps students have free or reduced-price meals.","template":"Studies have demonstrated that school meal programs play an important role in overall student health and academic achievement by improving children’s diets and combatting hunger. The National School Lunch Program helps students have free or reduced-price meals.","semantic_key":"school:nslp:nutrition_and_learning","copy_kind":"fact","source_url":"https://www.fns.usda.gov/nslp","evidence":"**Player-facing general fact:** “Studies have demonstrated that school meal programs play an important role in overall student health and academic achievement by improving children’s diets and combatting hunger. The National School Lunch Program helps students have free or reduced-price meals.”\n\n**General fact semantic key:** `school:nslp:nutrition_and_learning`\n\nSource/update: https://www.fns.usda.gov/nslp.  Approved revision from facts fixes.docx, November 15, 2026.\n"},{"role":"cac","text":"Students still need meals even when they are not in school during the summer. In 2025, Meals for Kids served 1,097 children.","template":"Students still need meals even when they are not in school during the summer. In 2025, Meals for Kids served 1,097 children.","semantic_key":"9496c5fe-de45-4ce7-96a9-4d6ba7f2ac01","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “Students still need meals even when they are not in school during the summer. In 2025, Meals for Kids served 1,097 children.”\n\nSource fact ID `9496c5fe-de45-4ce7-96a9-4d6ba7f2ac01`\n\nSource/update: https://ourcac.org/. CAC 2025 repository snapshot. children served by Meals for Kids: 1097 Number. Reporting year 2025. Annual refresh requires a CAC-provided report/export. User approved this pairing November 15, 2026. Approved revision from facts fixes.docx, November 15, 2026.\n\n"}]},{"key":"D015","description":"A repair completed before the month has a bill due today. The car is already repaired; this choice is about the unpaid invoice.","title":"The repair bill","facts":[{"role":"general","text":"A repair bill can keep taking up space in your budget after the car is back on the road.","template":"A repair bill can keep taking up space in your budget after the car is back on the road. In the past year, the average price of motor vehicle repair {change} by {pct}%.","semantic_key":"cpi:SETD03","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “A repair bill can keep taking up space in your budget after the car is back on the road. In the past year, the average price of motor vehicle repair {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SETD03`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SETD03. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D018","description":"Your household gas bill is due. Paying it will use some of the money you have set aside for other needs.","title":"The gas bill","facts":[{"role":"general","text":"Some U.S. households reported keeping their homes at unhealthy temperatures because of energy costs in the 2024 Residential Energy Consumption Survey.","template":"Some U.S. households reported keeping their homes at unhealthy temperatures because of energy costs in the 2024 Residential Energy Consumption Survey.","semantic_key":"energy:unhealthy_home_temperature","copy_kind":"fact","source_url":"https://www.eia.gov/consumption/residential/data/2024/hc/pdf/HC11.1_2024.pdf","evidence":"**Player-facing general fact:** “Some U.S. households reported keeping their homes at unhealthy temperatures because of energy costs in the 2024 Residential Energy Consumption Survey.”\n\n**General fact semantic key:** `energy:unhealthy_home_temperature`\n\nSource/update: S37, [EIA: 2024 household energy insecurity](https://www.eia.gov/consumption/residential/data/2024/hc/pdf/HC11.1_2024.pdf). Reported household energy insecurity, not specific to natural gas or proof of a local effect. Source checked November 7, 2026. Proposed qualitative display copy; initial content verification remains pending. Preserve the dated observation and semantic key on routine refresh; do not regenerate free-form claims automatically. No numerical binding is required for this passage.\n"},{"role":"cac","text":"A gas bill is part of the wider pressure of keeping a home running. In 2025, CAC reported preventing evictions for 1,108 households.","template":"A gas bill is part of the wider pressure of keeping a home running. In 2025, CAC reported preventing evictions for 1,108 households.","semantic_key":"5fa2bac7-6016-4db8-b705-fc593f6b75ec","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “A gas bill is part of the wider pressure of keeping a home running. In 2025, CAC reported preventing evictions for 1,108 households.”\n\nSource: S18/S19; fact ID `5fa2bac7-6016-4db8-b705-fc593f6b75ec`; service `eviction_prevention`; key `evictions_prevented`; reporting year 2025; exact stored value `1108` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. Household gas costs compete with rent and other essentials, connecting this decision to housing stability and eviction prevention. The user confirmed rent and utility bill support through CAC eviction prevention. Offer conditional CAC bill support in CAC mode; validate household eligibility and availability, cap assistance at the eligible bill balance, and bind the approved coverage amount separately from annual facts.\n\n"}]},{"key":"D019","description":"Rent is due just as you start to rebuild a cash buffer. Paying means giving up that buffer; ignoring creates a larger obligation.","title":"Rent or a cash cushion?","facts":[{"role":"general","text":"Rents in lower-cost, unsubsidized \"workforce housing\" sectors have risen sharply, with a recent study showing rents for low-wage Atlantans increasing up to nine times faster than rents for high earners.","template":"Rents in lower-cost, unsubsidized \"workforce housing\" sectors have risen sharply, with a recent study showing rents for low-wage Atlantans increasing up to nine times faster than rents for high earners.","semantic_key":"housing:atlanta:unequal_rent_growth","copy_kind":"fact","source_url":"https://www.ajc.com/news/2025/11/study-rents-for-low-wage-atlantans-rose-9-times-faster-than-for-high-earners/","evidence":"**Player-facing general fact:** “Rents in lower-cost, unsubsidized \"workforce housing\" sectors have risen sharply, with a recent study showing rents for low-wage Atlantans increasing up to nine times faster than rents for high earners.”\n\n**General fact semantic key:** `housing:atlanta:unequal_rent_growth`\n\nSource/update: https://www.ajc.com/news/2025/11/study-rents-for-low-wage-atlantans-rose-9-times-faster-than-for-high-earners/. User-approved dated claim. RentCast updates the scenario cost separately. Retain 2025 and do not extrapolate nine times to later periods. Approved revision from facts fixes.docx, November 15, 2026.\n"},{"role":"cac","text":"Rent pressure connects with the housing instability CAC financial assistance addresses. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.","template":"Rent pressure connects with the housing instability CAC financial assistance addresses. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.","semantic_key":"b697ae84-1fd2-4bae-83da-7a10c983ac24","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Rent pressure connects with the housing instability CAC financial assistance addresses. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.”\n\nSource: S18/S19; fact ID `b697ae84-1fd2-4bae-83da-7a10c983ac24`; service `financial_assistance`; key `amount_paid_through_financial_assistance`; reporting year 2025; exact stored value `796416.64` Dollars. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The scenario concerns rent pressure and preserving housing stability. Existing conditional rent pathway; annual spending is not the household’s benefit amount.\n\n"}]},{"key":"D020","description":"A medical bill is due. You can pay it now or leave the balance unpaid.","title":"A medical bill remains","facts":[{"role":"general","text":"An unpaid medical bill can remain part of the budget as new needs arrive.","template":"An unpaid medical bill can remain part of the budget as new needs arrive. In {period}, {pct}% of Sandy Springs civilian residents living outside institutions lacked health insurance.","semantic_key":"acs:B27001:uninsured","copy_kind":"context","source_url":"https://api.census.gov/data/2024/acs/acs5/groups.html","evidence":"**Player-facing general fact template:** “An unpaid medical bill can remain part of the budget as new needs arrive. In {period}, {pct}% of Sandy Springs civilian residents living outside institutions lacked health insurance.”\n\n**General fact semantic key:** `acs:B27001:uninsured`\n\nSource/update: https://api.census.gov/data/2024/acs/acs5/groups.html. **Player-facing general fact template:** “An unpaid medical bill can remain part of the budget as new needs arrive. In {period}, {pct}% of Sandy Springs civilian noninstitutionalized residents lacked health insurance.”\n\n**General fact semantic key:** `acs:B27001:uninsured`\n\nSource/update: S05 / A02; [S26 table catalogue](https://api.census.gov/data/2024/acs/acs5/groups.html), table B27001. Sum uninsured sex/age cells / table universe, with no overlapping age cells. Resolve exact estimate/MOE cells and Sandy Springs place geography against the selected annual five-year release; reject missing/suppressed values and zero denominators. Observation retrieval remains pending. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n Approved revision from facts fixes.docx, November 15, 2026.\n"},{"role":"cac","text":"Medical bills are a common cause of sudden financial crisis. In 2025, CAC contributed $796,416.64 to prevent homelessness, helping people stay safe and sheltered during times of crisis.","template":"Medical bills are a common cause of sudden financial crisis. In 2025, CAC contributed $796,416.64 to prevent homelessness, helping people stay safe and sheltered during times of crisis.","semantic_key":"b697ae84-1fd2-4bae-83da-7a10c983ac24","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “Medical bills are a common cause of sudden financial crisis. In 2025, CAC contributed $796,416.64 to prevent homelessness, helping people stay safe and sheltered during times of crisis.”\n\nSource fact ID `b697ae84-1fd2-4bae-83da-7a10c983ac24`\n\nSource/update: https://ourcac.org/. CAC 2025 repository snapshot. total financial assistance amount to prevent homelessness: 796416.64 Dollars. Reporting year 2025. Annual refresh requires a CAC-provided report/export. User approved this pairing November 15, 2026. Approved revision from facts fixes.docx, November 15, 2026.\n\n"}]},{"key":"D021","description":"The car will not start. The repair quote could use much of your remaining money, but you still need a way to get around.","title":"The car will not start","facts":[{"role":"general","text":"A lack of reliable transit cuts low-income workers off from the majority of the region's employment opportunities, worsening unemployment and limiting upward mobility.","template":"A lack of reliable transit cuts low-income workers off from the majority of the region's employment opportunities, worsening unemployment and limiting upward mobility.","semantic_key":"transit:access_to_employment","copy_kind":"fact","source_url":"https://www.urban.org/urban-wire/how-commuters-low-incomes-use-public-transit-and-how-one-city-expanded-ridership","evidence":"**Player-facing general fact:** “A lack of reliable transit cuts low-income workers off from the majority of the region's employment opportunities, worsening unemployment and limiting upward mobility.”\n\n**General fact semantic key:** `transit:access_to_employment`\n\nSource/update: https://www.urban.org/urban-wire/how-commuters-low-incomes-use-public-transit-and-how-one-city-expanded-ridership.  Approved revision from facts fixes.docx, November 15, 2026.\n"}]},{"key":"D022","description":"You have a painful dental problem. Treatment costs more than an assessment, and the assessment alone will not cover treatment.","title":"An unexpected dental expense","facts":[{"role":"general","text":"Dental care was the type of care U.S. adults most often reported skipping because of cost in the Federal Reserve's 2025 survey.","template":"Dental care was the type of care U.S. adults most often reported skipping because of cost in the Federal Reserve's 2025 survey.","semantic_key":"health:dental_most_skipped_care","copy_kind":"fact","source_url":"https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-economic-hardships.htm","evidence":"**Player-facing general fact:** “Dental care was the type of care U.S. adults most often reported skipping because of cost in the Federal Reserve's 2025 survey.”\n\n**General fact semantic key:** `health:dental_most_skipped_care`\n\nSource/update: S30, [Federal Reserve: economic hardships](https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-economic-hardships.htm). Comparison across care types, distinct from prescription and income-group facts. Source checked November 7, 2026. Proposed qualitative display copy; initial content verification remains pending. Preserve the dated observation and semantic key on routine refresh; do not regenerate free-form claims automatically. No numerical binding is required for this passage.\n"}]},{"key":"D024","description":"Someone close to you has a family emergency out of town. You want to be there, but the trip would use money set aside for your own household.","title":"A family emergency","facts":[{"role":"general","text":"In the Federal Reserve’s 2025 U.S. survey, 18% of adults regularly provided unpaid care for an adult relative or friend who needed help because of aging, disability or illness.","template":"In the Federal Reserve’s 2025 U.S. survey, 18% of adults regularly provided unpaid care for an adult relative or friend who needed help because of aging, disability or illness.","semantic_key":"care:unpaid_adult_relative_support","copy_kind":"fact","source_url":"https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-living-arrangements-care-work.htm","evidence":"**Player-facing general fact:** “In the Federal Reserve’s 2025 U.S. survey, 18% of adults regularly provided unpaid care for an adult relative or friend who needed help because of aging, disability or illness.”\n\n**General fact semantic key:** `care:unpaid_adult_relative_support`\n\nSource/update: https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-living-arrangements-care-work.htm. Overall adults, 2025 SHED. Preserve regular unpaid adult caregiving population. Retain this dated annual observation without automatic website requests. Approved revision from facts fixes.docx, November 15, 2026.\n"}]},{"key":"D025","description":"The person who usually watches Maya after school is sick and cannot care for her for the next two school days. Your shifts end after school lets out, so you need another plan.","title":"Childcare falls through","facts":[{"role":"general","text":"A Census Bureau study of U.S. households found that problems finding adequate childcare were accompanied by time away from work.","template":"A Census Bureau study of U.S. households found that problems finding adequate childcare were accompanied by time away from work.","semantic_key":"care:disruption_work_absence","copy_kind":"fact","source_url":"https://www.census.gov/library/working-papers/2026/demo/sehsd-wp2026-08.html","evidence":"**Player-facing general fact:** “A Census Bureau study of U.S. households found that problems finding adequate childcare were accompanied by time away from work.”\n\n**General fact semantic key:** `care:disruption_work_absence`\n\nSource/update: S32, [Census: childcare challenges](https://www.census.gov/library/working-papers/2026/demo/sehsd-wp2026-08.html). 2026 working paper, 2025 CPS ASEC about 2024; descriptive finding, not a predicted penalty for this choice. Source checked November 7, 2026. Proposed qualitative display copy; initial content verification remains pending. Preserve the dated observation and semantic key on routine refresh; do not regenerate free-form claims automatically. No numerical binding is required for this passage.\n"}]},{"key":"D026","description":"Your car needs tires. A new set costs a large part of your available money. The shop also has a lower-cost set.","title":"Time for new tires","facts":[{"role":"general","text":"New tires are another expense to weigh against keeping the car available.","template":"New tires are another expense to weigh against keeping the car available. In the past year, the average price of tires {change} by {pct}%.","semantic_key":"cpi:SETC01","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “New tires are another expense to weigh against keeping the car available. In the past year, the average price of tires {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SETC01`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SETC01. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D027","description":"Your work shoes are worn out and beginning to split. You need a usable pair for your next shift.","title":"Broken work shoes","facts":[{"role":"general","text":"With the rise of fast fashion manufacturing, many clothing items are lower quality and break after fewer wears. Low-income consumers can become trapped in a costly cycle of constantly replacing worn-out clothes.","template":"With the rise of fast fashion manufacturing, many clothing items are lower quality and break after fewer wears. Low-income consumers can become trapped in a costly cycle of constantly replacing worn-out clothes.","semantic_key":"clothing:quality_and_replacement_cost","copy_kind":"fact","source_url":"https://prospect.org/2025/08/29/2025-08-29-how-fast-fashion-keeps-people-poor/","evidence":"**Player-facing general fact:** “With the rise of fast fashion manufacturing, many clothing items are lower quality and break after fewer wears. Low-income consumers can become trapped in a costly cycle of constantly replacing worn-out clothes.”\n\n**General fact semantic key:** `clothing:quality_and_replacement_cost`\n\nSource/update: https://prospect.org/2025/08/29/2025-08-29-how-fast-fashion-keeps-people-poor/.  Approved revision from facts fixes.docx, November 15, 2026.\n"},{"role":"cac","text":"Canopy Thrift has a selective process to choose the items that make it to the floor, helping people gain access to higher quality items. In 2025, clients used $206,768.67 in Canopy Thrift credits.","template":"Canopy Thrift has a selective process to choose the items that make it to the floor, helping people gain access to higher quality items. In 2025, clients used $206,768.67 in Canopy Thrift credits.","semantic_key":"859b8cec-1e1c-4887-9f55-fd55f1bb349c","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “Canopy Thrift has a selective process to choose the items that make it to the floor, helping people gain access to higher quality items. In 2025, clients used $206,768.67 in Canopy Thrift credits.”\n\nSource fact ID `859b8cec-1e1c-4887-9f55-fd55f1bb349c`\n\nSource/update: https://ourcac.org/. CAC 2025 repository snapshot. dollar amount of client credits used at CAC Canopy Thrift: 206768.67 Dollars. Reporting year 2025. Annual refresh requires a CAC-provided report/export. User approved this pairing November 15, 2026. Approved revision from facts fixes.docx, November 15, 2026.\n\n"}]},{"key":"D028","description":"There is a plumbing problem at home, and the repair is your responsibility. You can pay for the full repair or a temporary fix.","title":"A plumbing problem","facts":[{"role":"general","text":"A plumbing problem can bring an expense that was never part of your plan for the month.","template":"A plumbing problem can bring an expense that was never part of your plan for the month. In {period}, {pct}% of occupied homes in Sandy Springs lacked complete plumbing facilities.","semantic_key":"acs:B25048:lacking_plumbing","copy_kind":"context","source_url":"https://api.census.gov/data/2024/acs/acs5/groups.html","evidence":"**Player-facing general fact template:** “A plumbing problem can bring an expense that was never part of your plan for the month. In {period}, {pct}% of occupied homes in Sandy Springs lacked complete plumbing facilities.”\n\n**General fact semantic key:** `acs:B25048:lacking_plumbing`\n\nSource/update: S05 / A02; [S26 table catalogue](https://api.census.gov/data/2024/acs/acs5/groups.html), table B25048. Occupied units lacking complete plumbing / all occupied units; does not measure temporary plumbing failures. Resolve exact estimate/MOE cells and Sandy Springs place geography against the selected annual five-year release; reject missing/suppressed values and zero denominators. Observation retrieval remains pending. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D029","description":"Maya needs a care appointment you had not budgeted for. You can pay for the full appointment or an initial appointment that leaves some care to arrange.","title":"An unexpected appointment for Maya","facts":[{"role":"general","text":"An unexpected appointment for Maya means finding money for care alongside other family needs.","template":"An unexpected appointment for Maya means finding money for care alongside other family needs. In the past year, the average price of services by other medical professionals {change} by {pct}%.","semantic_key":"cpi:SEMC04","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “An unexpected appointment for Maya means finding money for care alongside other family needs. In the past year, the average price of services by other medical professionals {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SEMC04`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SEMC04. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D030","description":"Your laptop fails. A replacement is expensive, and a repair quote is cheaper but would keep the same older device.","title":"A broken laptop","facts":[{"role":"general","text":"Lacking a full computer restricts workers from building digital skills, running heavy work software, and reliably completing remote employment or educational tasks that require larger screens and physical keyboards. Having more devices means more purchasing and repair costs that can strain families.","template":"Lacking a full computer restricts workers from building digital skills, running heavy work software, and reliably completing remote employment or educational tasks that require larger screens and physical keyboards. Having more devices means more purchasing and repair costs that can strain families.","semantic_key":"digital:full_computer_access","copy_kind":"fact","source_url":"https://publicknowledge.org/the-device-divide-is-hurting-americans-heres-how-we-solve-it/","evidence":"**Player-facing general fact:** “Lacking a full computer restricts workers from building digital skills, running heavy work software, and reliably completing remote employment or educational tasks that require larger screens and physical keyboards. Having more devices means more purchasing and repair costs that can strain families.”\n\n**General fact semantic key:** `digital:full_computer_access`\n\nSource/update: https://publicknowledge.org/the-device-divide-is-hurting-americans-heres-how-we-solve-it/.  Approved revision from facts fixes.docx, November 15, 2026.\n"}]},{"key":"D032","description":"You and your spouse need to make a household purchase, and your share is larger than expected. You can cover the full share or agree on a smaller contribution that leaves part of the purchase unfunded.","title":"A larger share to cover","facts":[{"role":"general","text":"Covering more of a shared purchase can leave less for your own needs.","template":"Covering more of a shared purchase can leave less for your own needs. In {period}, renter-occupied households in Sandy Springs averaged {persons} people.","semantic_key":"acs:B25010:renter_household_size","copy_kind":"context","source_url":"https://api.census.gov/data/2024/acs/acs5/groups.html","evidence":"**Player-facing general fact template:** “Covering more of a shared purchase can leave less for your own needs. In {period}, renter-occupied households in Sandy Springs averaged {persons} people.”\n\n**General fact semantic key:** `acs:B25010:renter_household_size`\n\nSource/update: S05 / A02; [S26 table catalogue](https://api.census.gov/data/2024/acs/acs5/groups.html), table B25010. Renter average household size; no percentage denominator or assumed equal cost sharing. Resolve exact estimate/MOE cells and Sandy Springs place geography against the selected annual five-year release; reject missing/suppressed values and zero denominators. Observation retrieval remains pending. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D033","description":"One of your small kitchen appliances became damaged and no longer works. You can buy the same version you had or look for something cheaper.","title":"A damaged small kitchen appliance","facts":[{"role":"general","text":"When cheap or older appliances break down completely, many low-income households cannot afford immediate replacements, forcing them to go without necessities. Older and cheaper appliances can also be less energy efficient, costing people even more in energy bills.","template":"When cheap or older appliances break down completely, many low-income households cannot afford immediate replacements, forcing them to go without necessities. Older and cheaper appliances can also be less energy efficient, costing people even more in energy bills.","semantic_key":"appliances:replacement_and_energy","copy_kind":"fact","source_url":"https://www.whirlpoolcorp.com/latest-news/habitat-whirlpool-study-illustrates-energy-efficient-appliances-can-help-low-income-families-lower-utility-bills.html","evidence":"**Player-facing general fact:** “When cheap or older appliances break down completely, many low-income households cannot afford immediate replacements, forcing them to go without necessities. Older and cheaper appliances can also be less energy efficient, costing people even more in energy bills.”\n\n**General fact semantic key:** `appliances:replacement_and_energy`\n\nSource/update: https://www.whirlpoolcorp.com/latest-news/habitat-whirlpool-study-illustrates-energy-efficient-appliances-can-help-low-income-families-lower-utility-bills.html. User-approved part 2 revision November 16, 2026. Qualitative educational context; retain source provenance.\n"},{"role":"cac","text":"Canopy Thrift helps neighbors access donated clothing and household essentials. In 2025, clients used $206,768.67 in Canopy Thrift credits.","template":"Canopy Thrift helps neighbors access donated clothing and household essentials. In 2025, clients used $206,768.67 in Canopy Thrift credits.","semantic_key":"859b8cec-1e1c-4887-9f55-fd55f1bb349c","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “Canopy Thrift helps neighbors access donated clothing and household essentials. In 2025, clients used $206,768.67 in Canopy Thrift credits.”\n\nSource fact ID `859b8cec-1e1c-4887-9f55-fd55f1bb349c`\n\nSource/update: https://ourcac.org/. User-approved part 2 revision November 16, 2026. CAC 2025 repository snapshot; annual report refresh remains required. This program fact does not guarantee item availability.\n\n"}]},{"key":"D034","description":"Your dresser breaks, leaving you without enough storage for your clothes. A complete replacement costs more than a basic option.","title":"A broken dresser","facts":[{"role":"general","text":"Replacing a broken dresser means choosing how much of your budget to spend on a household need.","template":"Replacing a broken dresser means choosing how much of your budget to spend on a household need. In the past year, the average price of bedroom furniture {change} by {pct}%.","semantic_key":"cpi:SEHJ01","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “Replacing a broken dresser means choosing how much of your budget to spend on a household need. In the past year, the average price of bedroom furniture {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SEHJ01`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SEHJ01. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Canopy Thrift helps neighbors access donated clothing and household essentials. In 2025, clients used $206,768.67 in Canopy Thrift credits.","template":"Canopy Thrift helps neighbors access donated clothing and household essentials. In 2025, clients used $206,768.67 in Canopy Thrift credits.","semantic_key":"859b8cec-1e1c-4887-9f55-fd55f1bb349c","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “Canopy Thrift helps neighbors access donated clothing and household essentials. In 2025, clients used $206,768.67 in Canopy Thrift credits.”\n\nSource fact ID `859b8cec-1e1c-4887-9f55-fd55f1bb349c`\n\nSource/update: https://ourcac.org/. User-approved part 2 revision November 16, 2026. CAC 2025 repository snapshot; annual report refresh remains required. This program fact does not guarantee item availability.\n\n"}]},{"key":"D035","description":"A refrigerator failure spoils your groceries. Replacing the food means spending money on something you already bought.","title":"Groceries lost","facts":[{"role":"general","text":"Losing groceries means paying again for food you had already planned to use.","template":"Losing groceries means paying again for food you had already planned to use. In the past year, the average price of groceries purchased for home use {change} by {pct}%.","semantic_key":"cpi:SAF11","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “Losing groceries means paying again for food you had already planned to use. In the past year, the average price of groceries purchased for home use {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SAF11`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SAF11. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Replacing lost groceries brings the need for food back into the budget. In 2025, the CAC Mini-Market reported 1,160,328 pounds of food available.","template":"Replacing lost groceries brings the need for food back into the budget. In 2025, the CAC Mini-Market reported 1,160,328 pounds of food available.","semantic_key":"efaf231b-3db3-4c4d-b276-758006af8aab","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Replacing lost groceries brings the need for food back into the budget. In 2025, the CAC Mini-Market reported 1,160,328 pounds of food available.”\n\nSource: S18/S19; fact ID `efaf231b-3db3-4c4d-b276-758006af8aab`; service `mini_market`; key `pounds_of_food_available_from_the_cac_mini_market`; reporting year 2025; exact stored value `1160328` Pounds. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The expense here is replacement groceries, not repairing the refrigerator. Free in-kind receipt: player balance change USD 0.00; no fee, cash deposit, cash-equivalent refund or debt. Record only the approved items/quantity actually received. Eligibility, availability, item scope and edition/service bindings remain pending; no entitlement to the priced retail alternative or complete basket is inferred. If the approved allocation meets only part of the need, record that need as partly unmet without charging a remainder or inventing a follow-up purchase. Any separately approved retail purchase is a distinct cost, never a CAC service fee. Annual facts do not determine individual quantities or benefit values.\n\n"}]},{"key":"D036","description":"You have a grocery list, but buying everything on it would leave little money for anything else.","title":"A full grocery basket?","facts":[{"role":"general","text":"Food insecurity can mean eating a less varied diet even when a household is still getting enough food to avoid cutting meal sizes.","template":"Food insecurity can mean eating a less varied diet even when a household is still getting enough food to avoid cutting meal sizes.","semantic_key":"food:reduced_diet_variety","copy_kind":"fact","source_url":"https://ers.usda.gov/topics/food-nutrition-assistance/food-security-in-the-us/measurement","evidence":"**Player-facing general fact:** “Food insecurity can mean eating a less varied diet even when a household is still getting enough food to avoid cutting meal sizes.”\n\n**General fact semantic key:** `food:reduced_diet_variety`\n\nSource/update: S33, [USDA: food-security measurement](https://ers.usda.gov/topics/food-nutrition-assistance/food-security-in-the-us/measurement). Paraphrases low food security definition; distinct from episodic shortages and child-specific measures. Source checked November 7, 2026. Proposed qualitative display copy; initial content verification remains pending. Preserve the dated observation and semantic key on routine refresh; do not regenerate free-form claims automatically. No numerical binding is required for this passage.\n"},{"role":"cac","text":"Food support can be part of finding a way to fill the next grocery basket. In 2025, there were 36,521 visits to the CAC Mini-Market.","template":"Food support can be part of finding a way to fill the next grocery basket. In 2025, there were 36,521 visits to the CAC Mini-Market.","semantic_key":"94210a01-4766-46ad-beba-d7400c9fd31e","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Food support can be part of finding a way to fill the next grocery basket. In 2025, there were 36,521 visits to the CAC Mini-Market.”\n\nSource: S18/S19; fact ID `94210a01-4766-46ad-beba-d7400c9fd31e`; service `mini_market`; key `visits_to_the_cac_mini_market`; reporting year 2025; exact stored value `36521` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The decision is grocery access and choosing a food basket. Free in-kind receipt: player balance change USD 0.00; no fee, cash deposit, cash-equivalent refund or debt. Record only the approved items/quantity actually received. Eligibility, availability, item scope and edition/service bindings remain pending; no entitlement to the priced retail alternative or complete basket is inferred. If the approved allocation meets only part of the need, record that need as partly unmet without charging a remainder or inventing a follow-up purchase. Any separately approved retail purchase is a distinct cost, never a CAC service fee. Annual facts do not determine individual quantities or benefit values.\n\n"}]},{"key":"D039","description":"Maya brings home an information sheet for joining the soccer team. The fee is modest compared with rent, but it is another claim on the same money.","title":"School Activities","facts":[{"role":"general","text":"Participating in school activities can provide social, emotional, physical and intellectual benefits for children. School activities also strengthen the connections with peers and with their school community, enhancing the likelihood of graduation and preventing dropouts. The costs for these activities can leave students out.","template":"Participating in school activities can provide social, emotional, physical and intellectual benefits for children. School activities also strengthen the connections with peers and with their school community, enhancing the likelihood of graduation and preventing dropouts. The costs for these activities can leave students out.","semantic_key":"school:activity_participation_barriers","copy_kind":"fact","source_url":"https://mottpoll.org/reports-surveys/pay-participate-limiting-school-activities-lower-income-students","evidence":"**Player-facing general fact:** “Participating in school activities can provide social, emotional, physical and intellectual benefits for children. School activities also strengthen the connections with peers and with their school community, enhancing the likelihood of graduation and preventing dropouts. The costs for these activities can leave students out.”\n\n**General fact semantic key:** `school:activity_participation_barriers`\n\nSource/update: https://mottpoll.org/reports-surveys/pay-participate-limiting-school-activities-lower-income-students. User-approved part 2 revision November 16, 2026. Qualitative educational context; retain source provenance.\n"}]},{"key":"D040","description":"Your coat is worn out. You can replace it or repair it.","title":"Worn-out coat","facts":[{"role":"general","text":"Cold weather makes the body work harder, putting stress on the heart to ensure the body stays warm, and exposure to the cold predisposes people to infections like pneumonia. Coats are an essential part of staying safe and healthy during the winter months.","template":"Cold weather makes the body work harder, putting stress on the heart to ensure the body stays warm, and exposure to the cold predisposes people to infections like pneumonia. Coats are an essential part of staying safe and healthy during the winter months.","semantic_key":"clothing:winter_cold_protection","copy_kind":"fact","source_url":"https://www.cdc.gov/winter-weather/prevention/index.html","evidence":"**Player-facing general fact:** “Cold weather makes the body work harder, putting stress on the heart to ensure the body stays warm, and exposure to the cold predisposes people to infections like pneumonia. Coats are an essential part of staying safe and healthy during the winter months.”\n\n**General fact semantic key:** `clothing:winter_cold_protection`\n\nSource/update: https://www.cdc.gov/winter-weather/prevention/index.html. User-approved part 2 revision November 16, 2026. Qualitative educational context; retain source provenance.\n"},{"role":"cac","text":"Canopy Thrift helps neighbors access donated clothing and household essentials. In 2025, clients used $206,768.67 in Canopy Thrift credits.","template":"Canopy Thrift helps neighbors access donated clothing and household essentials. In 2025, clients used $206,768.67 in Canopy Thrift credits.","semantic_key":"859b8cec-1e1c-4887-9f55-fd55f1bb349c","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “Canopy Thrift helps neighbors access donated clothing and household essentials. In 2025, clients used $206,768.67 in Canopy Thrift credits.”\n\nSource fact ID `859b8cec-1e1c-4887-9f55-fd55f1bb349c`\n\nSource/update: https://ourcac.org/. User-approved part 2 revision November 16, 2026. CAC 2025 repository snapshot; annual report refresh remains required. This program fact does not guarantee item availability.\n\n"}]},{"key":"D042","description":"Maya needs supplies for an upcoming school activity. You can buy the complete set or just the immediate required items.","title":"School supplies for Maya","facts":[{"role":"general","text":"School supplies create another shopping list when the household budget is already committed.","template":"School supplies create another shopping list when the household budget is already committed. In the past year, the average price of educational books and supplies {change} by {pct}%.","semantic_key":"cpi:SEEA","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “School supplies create another shopping list when the household budget is already committed. In the past year, the average price of educational books and supplies {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SEEA`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SEEA. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"School supplies are the need at the center of Tools for School. In 2025, Tools for School served 1,090 children.","template":"School supplies are the need at the center of Tools for School. In 2025, Tools for School served 1,090 children.","semantic_key":"c6a72bf1-47ac-4d53-9adc-8ad68dd120c4","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “School supplies are the need at the center of Tools for School. In 2025, Tools for School served 1,090 children.”\n\nSource: S18/S19; fact ID `c6a72bf1-47ac-4d53-9adc-8ad68dd120c4`; service `tools_for_school`; key `children_served_by_tools_for_school`; reporting year 2025; exact stored value `1090` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The decision is specifically school supplies for a child. Free in-kind receipt: player balance change USD 0.00; no fee, cash deposit, cash-equivalent refund or debt. Record only the approved items/quantity actually received. Eligibility, availability, item scope and edition/service bindings remain pending; no entitlement to the priced retail alternative or complete basket is inferred. If the approved allocation meets only part of the need, record that need as partly unmet without charging a remainder or inventing a follow-up purchase. Any separately approved retail purchase is a distinct cost, never a CAC service fee. Annual facts do not determine individual quantities or benefit values.\n\n"}]},{"key":"D043","description":"A child in your family has a birthday coming up. You can buy the gift you planned, choose a smaller gift, or give your time.","title":"A family birthday","facts":[{"role":"general","text":"A family birthday can mean balancing a gesture of care with money needed for essentials.","template":"A family birthday can mean balancing a gesture of care with money needed for essentials. In the past year, the average price of stationery, supplies and gift wrap {change} by {pct}%.","semantic_key":"cpi:SS33032","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “A family birthday can mean balancing a gesture of care with money needed for essentials. In the past year, the average price of stationery, supplies and gift wrap {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SS33032`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SS33032. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D044","description":"You have a household appointment across town that you will need a ride to. A direct ride costs more, while the transit route takes longer.","title":"Getting to an appointment","facts":[{"role":"general","text":"Getting to an appointment can mean choosing between a higher fare and more time in transit.","template":"Getting to an appointment can mean choosing between a higher fare and more time in transit. In {period}, {pct}% of Sandy Springs households had no vehicle available.","semantic_key":"acs:B08201:no_vehicle_households","copy_kind":"context","source_url":"https://api.census.gov/data/2024/acs/acs5/groups.html","evidence":"**Player-facing general fact template:** “Getting to an appointment can mean choosing between a higher fare and more time in transit. In {period}, {pct}% of Sandy Springs households had no vehicle available.”\n\n**General fact semantic key:** `acs:B08201:no_vehicle_households`\n\nSource/update: S05 / A02; [S26 table catalogue](https://api.census.gov/data/2024/acs/acs5/groups.html), table B08201. Sum household-size categories with zero vehicles / all households; no inference about the player. Resolve exact estimate/MOE cells and Sandy Springs place geography against the selected annual five-year release; reject missing/suppressed values and zero denominators. Observation retrieval remains pending. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D045","description":"Cold weather is here, and Maya needs a coat. You can buy a new one or a less expensive secondhand coat.","title":"A coat for Maya","facts":[{"role":"general","text":"Coats are often the most expensive item in a child’s wardrobe, yet they tend to outgrow them quickly. Tight budgets can leave little room for seasonal clothing, yet clothing is not covered by major federal safety nets as food and healthcare are. Not having a coat can lead to school absences, physical health risks, or poor emotional well-being.","template":"Coats are often the most expensive item in a child’s wardrobe, yet they tend to outgrow them quickly. Tight budgets can leave little room for seasonal clothing, yet clothing is not covered by major federal safety nets as food and healthcare are. Not having a coat can lead to school absences, physical health risks, or poor emotional well-being.","semantic_key":"clothing:child_clothing_insecurity","copy_kind":"fact","source_url":"https://noteinthepocket.org/clothing-insecurity/","evidence":"**Player-facing general fact:** “Coats are often the most expensive item in a child’s wardrobe, yet they tend to outgrow them quickly. Tight budgets can leave little room for seasonal clothing, yet clothing is not covered by major federal safety nets as food and healthcare are. Not having a coat can lead to school absences, physical health risks, or poor emotional well-being.”\n\n**General fact semantic key:** `clothing:child_clothing_insecurity`\n\nSource/update: https://noteinthepocket.org/clothing-insecurity/. User-approved part 2 revision November 16, 2026. Qualitative educational context; retain source provenance.\n"},{"role":"cac","text":"A warm coat is the need at the center of Coats for Kids. In 2025, Coats for Kids served 623 children.","template":"A warm coat is the need at the center of Coats for Kids. In 2025, Coats for Kids served 623 children.","semantic_key":"e8473e58-6338-4855-93be-7608f27696ab","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “A warm coat is the need at the center of Coats for Kids. In 2025, Coats for Kids served 623 children.”\n\nSource: S18/S19; fact ID `e8473e58-6338-4855-93be-7608f27696ab`; service `coats_for_kids`; key `children_served_by_coats_for_kids`; reporting year 2025; exact stored value `623` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The need is a child’s warm coat in the program’s season. Free in-kind receipt: player balance change USD 0.00; no fee, cash deposit, cash-equivalent refund or debt. Record only the approved items/quantity actually received. Eligibility, availability, item scope and edition/service bindings remain pending; no entitlement to the priced retail alternative or complete basket is inferred. If the approved allocation meets only part of the need, record that need as partly unmet without charging a remainder or inventing a follow-up purchase. Any separately approved retail purchase is a distinct cost, never a CAC service fee. Annual facts do not determine individual quantities or benefit values.\n\n"}]},{"key":"D046","description":"You can prepare lunches ahead of time or get lunch out with your coworkers. One option takes more time now; the other costs more money.","title":"Packing lunch or buying it?","facts":[{"role":"general","text":"Sharing a meal can be about more than food. A 2017 study found that people who ate with others more often reported greater life satisfaction and more friends they could rely on.","template":"Sharing a meal can be about more than food. A 2017 study found that people who ate with others more often reported greater life satisfaction and more friends they could rely on.","semantic_key":"social:shared_meals_connection","copy_kind":"fact","source_url":"https://doi.org/10.1007/s40750-017-0061-4","evidence":"**Player-facing general fact:** “Sharing a meal can be about more than food. A 2017 study found that people who ate with others more often reported greater life satisfaction and more friends they could rely on.”\n\n**General fact semantic key:** `social:shared_meals_connection`\n\nSource/update: https://doi.org/10.1007/s40750-017-0061-4. Dunbar (2017), Breaking Bread: the Functions of Social Eating. UK national survey; association, not proof that buying lunch causes wellbeing or that packed lunches prevent social contact. User approved this passage without “UK” in the displayed wording on November 17, 2026. Static dated research fact; monthly price bindings remain separate.\n"},{"role":"cac","text":"The CAC Mini-Market helps households obtain groceries, including food to prepare meals. In 2025, it served 7,034 individuals.","template":"The CAC Mini-Market helps households obtain groceries, including food to prepare meals. In 2025, it served 7,034 individuals.","semantic_key":"0a3f963a-b2c5-47d6-8b9d-e0d396da6a66","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “The CAC Mini-Market helps households obtain groceries, including food to prepare meals. In 2025, it served 7,034 individuals.”\n\nSource fact ID `0a3f963a-b2c5-47d6-8b9d-e0d396da6a66`\n\nSource/update: https://ourcac.org/. User-approved part 2 revision November 16, 2026. CAC 2025 repository snapshot; annual report refresh remains required. This program fact does not guarantee item availability.\n\n"}]},{"key":"D047","description":"The bag you use for everyday travel breaks. You can replace it or pay for a repair.","title":"A broken bag","facts":[{"role":"general","text":"A replacement bag is one of the personal goods that can become an unexpected purchase.","template":"A replacement bag is one of the personal goods that can become an unexpected purchase. In the past year, the average price of miscellaneous personal goods {change} by {pct}%.","semantic_key":"cpi:SEGE","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “A replacement bag is one of the personal goods that can become an unexpected purchase. In the past year, the average price of miscellaneous personal goods {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SEGE`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SEGE. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D048","description":"Maya needs meals during a period when school is out of session.","title":"Meals for Maya","facts":[{"role":"general","text":"Missing meals and experiencing chronic hunger significantly impact children's physical growth, cognitive development, and mental health. This becomes a larger issue when school is out of session and it is up to households to find a child’s next meal.","template":"Missing meals and experiencing chronic hunger significantly impact children's physical growth, cognitive development, and mental health. This becomes a larger issue when school is out of session and it is up to households to find a child’s next meal.","semantic_key":"food:child_hunger_school_breaks","copy_kind":"fact","source_url":"https://www.nokidhungry.org/blog/effects-of-hunger-on-the-body","evidence":"**Player-facing general fact:** “Missing meals and experiencing chronic hunger significantly impact children's physical growth, cognitive development, and mental health. This becomes a larger issue when school is out of session and it is up to households to find a child’s next meal.”\n\n**General fact semantic key:** `food:child_hunger_school_breaks`\n\nSource/update: https://www.nokidhungry.org/blog/effects-of-hunger-on-the-body. User-approved part 2 revision November 16, 2026. Qualitative educational context; retain source provenance.\n"},{"role":"cac","text":"Meals for Kids connects with the need to plan food for Maya. In 2025, Meals for Kids served 1,097 children.","template":"Meals for Kids connects with the need to plan food for Maya. In 2025, Meals for Kids served 1,097 children.","semantic_key":"9496c5fe-de45-4ce7-96a9-4d6ba7f2ac01","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Meals for Kids connects with the need to plan food for Maya. In 2025, Meals for Kids served 1,097 children.”\n\nSource: S18/S19; fact ID `9496c5fe-de45-4ce7-96a9-4d6ba7f2ac01`; service `meals_for_kids`; key `children_served_by_meals_for_kids`; reporting year 2025; exact stored value `1097` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The scenario explicitly covers meals for a child during the program period. Free in-kind receipt: player balance change USD 0.00; no fee, cash deposit, cash-equivalent refund or debt. Record only the approved items/quantity actually received. Eligibility, availability, item scope and edition/service bindings remain pending; no entitlement to the priced retail alternative or complete basket is inferred. If the approved allocation meets only part of the need, record that need as partly unmet without charging a remainder or inventing a follow-up purchase. Any separately approved retail purchase is a distinct cost, never a CAC service fee. Annual facts do not determine individual quantities or benefit values.\n\n"}]},{"key":"D049","description":"You need to access your money. One option charges a fee; a slower option is free.","title":"A fee to access your money","facts":[{"role":"general","text":"People without bank accounts have cited high or unpredictable fees and minimum balance requirements among their reasons for staying outside the banking system.","template":"People without bank accounts have cited high or unpredictable fees and minimum balance requirements among their reasons for staying outside the banking system.","semantic_key":"banking:reported_access_barriers","copy_kind":"fact","source_url":"https://www.federalreserve.gov/newsevents/speech/barr20250715a.htm","evidence":"**Player-facing general fact:** “People without bank accounts have cited high or unpredictable fees and minimum balance requirements among their reasons for staying outside the banking system.”\n\n**General fact semantic key:** `banking:reported_access_barriers`\n\nSource/update: S36, [Federal Reserve: financial inclusion](https://www.federalreserve.gov/newsevents/speech/barr20250715a.htm). Reported reasons, not evidence that every account has these charges or that the player is unbanked. Source checked November 7, 2026. Proposed qualitative display copy; initial content verification remains pending. Preserve the dated observation and semantic key on routine refresh; do not regenerate free-form claims automatically. No numerical binding is required for this passage.\n"},{"role":"cac","text":"Comparing a fee with a free alternative is part of making your money stretch. In 2025, 218 students enrolled in Financial Literacy Classes.","template":"Comparing a fee with a free alternative is part of making your money stretch. In 2025, 218 students enrolled in Financial Literacy Classes.","semantic_key":"d32689c8-067a-4f59-aa48-2424384b7116","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Comparing a fee with a free alternative is part of making your money stretch. In 2025, 218 students enrolled in Financial Literacy Classes.”\n\nSource: S18/S19; fact ID `d32689c8-067a-4f59-aa48-2424384b7116`; service `financial_literacy_classes`; key `students_enrolled_in_financial_literacy_classes`; reporting year 2025; exact stored value `218` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. Comparing a fee-charging money-access route with a free route is financial-literacy context. Context only; no claim that CAC pays fees or offers the payment instrument.\n\n"}]},{"key":"D050","description":"You are running low on household hygiene supplies. Buying the larger pack costs more today, while the smaller pack leaves more cash available.","title":"Running low on essentials","facts":[{"role":"general","text":"Running low on essentials means deciding how much you can buy with the cash available.","template":"Running low on essentials means deciding how much you can buy with the cash available. In the past year, the average price of personal care products {change} by {pct}%.","semantic_key":"cpi:SEGB","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “Running low on essentials means deciding how much you can buy with the cash available. In the past year, the average price of personal care products {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SEGB`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SEGB. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D051","description":"There is a skills workshop you would like to attend. The fee would leave less money for other needs.","title":"A chance to learn","facts":[{"role":"general","text":"Training can give people valuable skills for the workplace. Because they cannot afford the upfront time or money to participate, low-income families can miss out on income boosts from having advanced skills.","template":"Training can give people valuable skills for the workplace. Because they cannot afford the upfront time or money to participate, low-income families can miss out on income boosts from having advanced skills.","semantic_key":"education:training_time_and_cost_barriers","copy_kind":"fact","source_url":"https://www.oecd.org/en/publications/trends-in-adult-learning_ec0624a6-en.html","evidence":"**Player-facing general fact:** “Training can give people valuable skills for the workplace. Because they cannot afford the upfront time or money to participate, low-income families can miss out on income boosts from having advanced skills.”\n\n**General fact semantic key:** `education:training_time_and_cost_barriers`\n\nSource/update: https://www.oecd.org/en/publications/trends-in-adult-learning_ec0624a6-en.html. User-approved part 2 revision November 16, 2026. Qualitative educational context; retain source provenance.\n"},{"role":"cac","text":"CAC Adult Education offers opportunities to develop skills. In 2025, its adult education programs served 610 students.","template":"CAC Adult Education offers opportunities to develop skills. In 2025, its adult education programs served 610 students.","semantic_key":"7cb64039-5726-43da-8f15-fbf8b63e8f83","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact:** “CAC Adult Education offers opportunities to develop skills. In 2025, its adult education programs served 610 students.”\n\nSource fact ID `7cb64039-5726-43da-8f15-fbf8b63e8f83`\n\nSource/update: https://ourcac.org/. User-approved part 2 revision November 16, 2026. CAC 2025 repository snapshot; annual report refresh remains required. This program fact does not guarantee item availability.\n\n"}]},{"key":"D053","description":"You can buy all the food that is a part of your normal family traditions, or a smaller selection that costs less.","title":"A holiday meal","facts":[{"role":"general","text":"Turkey can be one of the ingredients to budget for when planning a holiday meal.","template":"Turkey can be one of the ingredients to budget for when planning a holiday meal. In the past year, the average price of uncooked poultry other than chicken {change} by {pct}%.","semantic_key":"cpi:SEFF02","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “Turkey can be one of the ingredients to budget for when planning a holiday meal. In the past year, the average price of uncooked poultry other than chicken {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SEFF02`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SEFF02. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Holiday food support connects with putting a seasonal meal on the table. In 2025, 984 households received Holiday Food Baskets.","template":"Holiday food support connects with putting a seasonal meal on the table. In 2025, 984 households received Holiday Food Baskets.","semantic_key":"1eec83c9-41ca-4aef-be22-1e36289d9d95","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Holiday food support connects with putting a seasonal meal on the table. In 2025, 984 households received Holiday Food Baskets.”\n\nSource: S18/S19; fact ID `1eec83c9-41ca-4aef-be22-1e36289d9d95`; service `holiday_food_baskets`; key `households_who_received_holiday_food_baskets`; reporting year 2025; exact stored value `984` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The need is a distinct seasonal holiday food basket. Free in-kind receipt: player balance change USD 0.00; no fee, cash deposit, cash-equivalent refund or debt. Record only the approved items/quantity actually received. Eligibility, availability, item scope and edition/service bindings remain pending; no entitlement to the priced retail alternative or complete basket is inferred. If the approved allocation meets only part of the need, record that need as partly unmet without charging a remainder or inventing a follow-up purchase. Any separately approved retail purchase is a distinct cost, never a CAC service fee. Annual facts do not determine individual quantities or benefit values.\n\n"}]},{"key":"D054","description":"An everyday clothing item needs replacing. Buying it new costs more than buying it secondhand.","title":"Clothes need replacing","facts":[{"role":"general","text":"Replacing worn clothing means balancing what you need now with money needed elsewhere.","template":"Replacing worn clothing means balancing what you need now with money needed elsewhere. In the past year, the average price of clothing other than footwear {change} by {pct}%.","semantic_key":"cpi:SA311","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “Replacing worn clothing means balancing what you need now with money needed elsewhere. In the past year, the average price of clothing other than footwear {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SA311`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SA311. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Clothing credits are one way CAC supports access to replacement clothing. In 2025, clients used $206,768.67 in credits at CAC Canopy Thrift.","template":"Clothing credits are one way CAC supports access to replacement clothing. In 2025, clients used $206,768.67 in credits at CAC Canopy Thrift.","semantic_key":"859b8cec-1e1c-4887-9f55-fd55f1bb349c","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Clothing credits are one way CAC supports access to replacement clothing. In 2025, clients used $206,768.67 in credits at CAC Canopy Thrift.”\n\nSource: S18/S19; fact ID `859b8cec-1e1c-4887-9f55-fd55f1bb349c`; service `canopy_thrift`; key `dollar_amount_of_client_credits_used_at_cac_canopy_thrift`; reporting year 2025; exact stored value `206768.67` Dollars. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The decision concerns replacement clothing and a lower-cost alternative. Free in-kind receipt: player balance change USD 0.00; no fee, cash deposit, cash-equivalent refund or debt. Record only the approved items/quantity actually received. Eligibility, availability, item scope and edition/service bindings remain pending; no entitlement to the priced retail alternative or complete basket is inferred. If the approved allocation meets only part of the need, record that need as partly unmet without charging a remainder or inventing a follow-up purchase. Any separately approved retail purchase is a distinct cost, never a CAC service fee. Annual facts do not determine individual quantities or benefit values.\n\n"}]},{"key":"D055","description":"Someone you care about asks for help with an unexpected expense. Helping them leaves less for your own household.","title":"Someone asks for help","facts":[{"role":"general","text":"Helping someone else means deciding how much room is left in your own budget.","template":"Helping someone else means deciding how much room is left in your own budget. In {period}, {pct}% of Sandy Springs families lived below the poverty threshold.","semantic_key":"acs:B17010:family_poverty","copy_kind":"context","source_url":"https://api.census.gov/data/2024/acs/acs5/groups.html","evidence":"**Player-facing general fact template:** “Helping someone else means deciding how much room is left in your own budget. In {period}, {pct}% of Sandy Springs families lived below the poverty threshold.”\n\n**General fact semantic key:** `acs:B17010:family_poverty`\n\nSource/update: S05 / A02; [S26 table catalogue](https://api.census.gov/data/2024/acs/acs5/groups.html), table B17010. Below-poverty families / all families in table; distinct from resident poverty rate. Resolve exact estimate/MOE cells and Sandy Springs place geography against the selected annual five-year release; reject missing/suppressed values and zero denominators. Observation retrieval remains pending. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Deciding what you can give means taking your own financial commitments into account. In 2025, 218 students enrolled in Financial Literacy Classes.","template":"Deciding what you can give means taking your own financial commitments into account. In 2025, 218 students enrolled in Financial Literacy Classes.","semantic_key":"d32689c8-067a-4f59-aa48-2424384b7116","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Deciding what you can give means taking your own financial commitments into account. In 2025, 218 students enrolled in Financial Literacy Classes.”\n\nSource: S18/S19; fact ID `d32689c8-067a-4f59-aa48-2424384b7116`; service `financial_literacy_classes`; key `students_enrolled_in_financial_literacy_classes`; reporting year 2025; exact stored value `218` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. Balancing help for another person against one’s own budget is financial-literacy context. Context only; no CAC reimbursement, loan, or moral score.\n\n"}]},{"key":"D056","description":"You are considering a holiday gift for Maya. The planned gift costs more than a modest alternative.","title":"A holiday gift for Maya","facts":[{"role":"general","text":"A holiday gift can be meaningful while still competing with everyday expenses.","template":"A holiday gift can be meaningful while still competing with everyday expenses. In the past year, the average price of toys {change} by {pct}%.","semantic_key":"cpi:SERE01","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “A holiday gift can be meaningful while still competing with everyday expenses. In the past year, the average price of toys {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SERE01`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SERE01. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"},{"role":"cac","text":"Hope for the Holidays connects with the wish to include a child in seasonal gift giving. In 2025, Hope for the Holidays served 614 households.","template":"Hope for the Holidays connects with the wish to include a child in seasonal gift giving. In 2025, Hope for the Holidays served 614 households.","semantic_key":"18b975be-96cb-49ec-901b-ccd04c6c6a5c","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Hope for the Holidays connects with the wish to include a child in seasonal gift giving. In 2025, Hope for the Holidays served 614 households.”\n\nSource: S18/S19; fact ID `18b975be-96cb-49ec-901b-ccd04c6c6a5c`; service `hope_for_the_holidays`; key `households_served_by_hope_for_the_holidays`; reporting year 2025; exact stored value `614` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. The card explicitly concerns the named holiday program and a child’s holiday gift. Free in-kind receipt: player balance change USD 0.00; no fee, cash deposit, cash-equivalent refund or debt. Record only the approved items/quantity actually received. Eligibility, availability, item scope and edition/service bindings remain pending; no entitlement to the priced retail alternative or complete basket is inferred. If the approved allocation meets only part of the need, record that need as partly unmet without charging a remainder or inventing a follow-up purchase. Any separately approved retail purchase is a distinct cost, never a CAC service fee. Annual facts do not determine individual quantities or benefit values.\n\n"}]},{"key":"D058","description":"You and your spouse need laundry supplies. A larger purchase costs more today; buying only the immediate amount keeps cash available.","title":"Laundry supplies are running low","facts":[{"role":"general","text":"Buying laundry supplies means balancing what you need now against the cost of a larger pack.","template":"Buying laundry supplies means balancing what you need now against the cost of a larger pack. In the past year, the average price of household cleaning products {change} by {pct}%.","semantic_key":"cpi:SEHN01","copy_kind":"context","source_url":"https://www.bls.gov/cpi/additional-resources/index-publication-level.htm","evidence":"**Player-facing general fact template:** “Buying laundry supplies means balancing what you need now against the cost of a larger pack. In the past year, the average price of household cleaning products {change} by {pct}%.”\n\n**General fact semantic key:** `cpi:SEHN01`\n\nSource/update: S01 / A01; [S25 category catalogue](https://www.bls.gov/cpi/additional-resources/index-publication-level.htm). Candidate CPI-U non-seasonally-adjusted series CUUR0000SEHN01. U.S. city average, not a Sandy Springs observation. Calculate 100 * (latest nonmissing index / base index - 1), using the same published series and a configured comparison period. Category is factual context, not the exact scenario product price. Endpoint observations/series availability still require validation before display. Initial binding verification is pending; subsequent validated observations update and publish automatically.\n"}]},{"key":"D059","description":"You have an opportunity to spend time with a friend. The planned outing costs money; an agreed free alternative is available.","title":"Time with a friend","facts":[{"role":"general","text":"Americans were less likely to spend time socializing or communicating on an average day in 2025 than in 2015, according to the U.S. time-use survey.","template":"Americans were less likely to spend time socializing or communicating on an average day in 2025 than in 2015, according to the U.S. time-use survey.","semantic_key":"social:less_daily_socializing","copy_kind":"fact","source_url":"https://www.bls.gov/news.release/archives/atus_06252026.htm","evidence":"**Player-facing general fact:** “Americans were less likely to spend time socializing or communicating on an average day in 2025 than in 2015, according to the U.S. time-use survey.”\n\n**General fact semantic key:** `social:less_daily_socializing`\n\nSource/update: S34, [BLS: 2025 American Time Use Survey](https://www.bls.gov/news.release/archives/atus_06252026.htm). Release comparison across years; does not establish that paid outings improve well-being or that socializing requires money. Source checked November 7, 2026. Proposed qualitative display copy; initial content verification remains pending. Preserve the dated observation and semantic key on routine refresh; do not regenerate free-form claims automatically. No numerical binding is required for this passage.\n"},{"role":"cac","text":"Finding room for a paid outing is one of the choices involved in managing a budget. In 2025, 218 students enrolled in Financial Literacy Classes.","template":"Finding room for a paid outing is one of the choices involved in managing a budget. In 2025, 218 students enrolled in Financial Literacy Classes.","semantic_key":"d32689c8-067a-4f59-aa48-2424384b7116","copy_kind":"fact","source_url":"https://ourcac.org/","evidence":"**Player-facing CAC fact template:** “Finding room for a paid outing is one of the choices involved in managing a budget. In 2025, 218 students enrolled in Financial Literacy Classes.”\n\nSource: S18/S19; fact ID `d32689c8-067a-4f59-aa48-2424384b7116`; service `financial_literacy_classes`; key `students_enrolled_in_financial_literacy_classes`; reporting year 2025; exact stored value `218` Number. Status: existing pairing for review, not publication approval. Update through a CAC-approved report/export and protected backend ingestion; no public CAC API has been established. Require original report/page or staff certification before final factual review. Choosing between a paid outing and a free alternative is a discretionary-budget tradeoff. Context only; no claim of CAC leisure funding or a judgment about spending.\n\n"}]}]$templates$;
 observations jsonb; series jsonb; latest jsonb; previous jsonb; pct numeric; rendered text; vid uuid;
BEGIN
 SELECT source_snapshot INTO STRICT payload FROM public.scenario_edition_prices
 WHERE version_id=(SELECT version_id FROM public.content_versions WHERE status='published' ORDER BY version_number DESC LIMIT 1);
 payload:=replace(payload::text,'â€™','’')::jsonb;
 payload:=replace(payload::text,'â€˜','‘')::jsonb;
 payload:=replace(payload::text,'â€œ','“')::jsonb;
 payload:=replace(payload::text,'â€','”')::jsonb;
 payload:=replace(payload::text,'â€“','–')::jsonb;
 payload:=replace(payload::text,'â€”','—')::jsonb;
 payload:=replace(payload::text,'â€¦','…')::jsonb;
 payload:=replace(payload::text,'Â·','·')::jsonb;
 payload:=replace(payload::text,'Â ',' ')::jsonb;
 SELECT result->'observations' INTO observations FROM public.game_data_refresh_runs ORDER BY period DESC LIMIT 1;
 FOR c IN SELECT * FROM jsonb_array_elements(payload->'cards') LOOP
  SELECT t INTO STRICT fresh FROM jsonb_array_elements(templates) t WHERE t->>'key'=c->>'key';
  facts:='[]';
  FOR f IN SELECT * FROM jsonb_array_elements(fresh->'facts') LOOP
   SELECT item INTO old_fact FROM jsonb_array_elements(c->'facts') item WHERE item->>'role'=f->>'role';
   IF (f->>'template') LIKE '%{%' THEN
    IF f->>'semantic_key' LIKE 'cpi:%' THEN
     series:=observations->('CUUR0000'||split_part(f->>'semantic_key',':',2));
     SELECT observed.value,earlier.value INTO latest,previous
     FROM jsonb_array_elements(coalesce(series,'[]')) observed
     JOIN jsonb_array_elements(coalesce(series,'[]')) earlier
      ON earlier.value->>'period'=((left(observed.value->>'period',4)::integer-1)::text||substring(observed.value->>'period' from 5))
     ORDER BY observed.value->>'period' DESC LIMIT 1;
     IF latest IS NOT NULL AND previous IS NOT NULL THEN
      pct:=100*((latest->>'value')::numeric/(previous->>'value')::numeric-1);
      rendered:=replace(replace(replace(replace(f->>'template','{base observation period}',previous->>'period'),'{latest observation period}',latest->>'period'),'{pct}',to_char(abs(round(pct,1)),'FM999990.0')),'{change}',CASE WHEN pct<0 THEN 'decreased' ELSE 'increased' END);
      IF pct=0 THEN rendered:=replace(rendered,'increased by 0.0%.','did not change.'); END IF;
      f:=f||jsonb_build_object('text',rendered,'copy_kind','fact');
     ELSE
      f:=f||jsonb_build_object('text',coalesce(old_fact->>'text',f->>'text'),'copy_kind',coalesce(old_fact->>'copy_kind',f->>'copy_kind'));
     END IF;
    ELSIF old_fact->>'semantic_key'=f->>'semantic_key' THEN
     f:=old_fact||f||jsonb_build_object('text',old_fact->>'text','copy_kind',old_fact->>'copy_kind','source_url',old_fact->>'source_url');
    END IF;
   END IF;
   facts:=facts||jsonb_build_array(f);
  END LOOP;
  cards:=cards||jsonb_build_array(c||jsonb_build_object('facts',facts,'description',fresh->'description','title',fresh->'title'));
 END LOOP;
 payload:=payload||jsonb_build_object('cards',cards,'sourceHash','5191a1eaeacb59c010c9762fe6d293660e82a96acbd9cfe9780f4bc0c9c9ff6b');
 vid:=public.publish_scenario_source_edition(payload);
 UPDATE public.content_versions SET change_summary='Proofread authored facts, correct encoding and regular-mode descriptions, and resolve latest complete annual fact comparisons; preserve prices and verification dates.' WHERE version_id=vid;
END $copy$;
COMMIT;
